CREATE UNIQUE INDEX IF NOT EXISTS u_accounts__payments_stripeAccountId ON c_accounts (json_extract(data, '$.payments.stripeAccountId') ASC) WHERE json_type(data, '$.payments.stripeAccountId') = 'text';
CREATE TABLE IF NOT EXISTS c_buyers (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_buyers__accountId ON c_buyers (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_buyers__accountId__email ON c_buyers (accountId ASC, json_extract(data, '$.email') ASC);
CREATE INDEX IF NOT EXISTS i_contacts__stripeSubscriptionId ON c_contacts (json_extract(data, '$.stripeSubscriptionId') ASC) WHERE json_type(data, '$.stripeSubscriptionId') = 'text';
CREATE INDEX IF NOT EXISTS i_contacts__newsletterId__stripeCustomerId ON c_contacts (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.stripeCustomerId') ASC) WHERE json_type(data, '$.stripeCustomerId') = 'text';
CREATE INDEX IF NOT EXISTS i_contacts__newsletterId__tier__status ON c_contacts (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.tier') ASC, json_extract(data, '$.status') ASC);
CREATE TABLE IF NOT EXISTS c_orders (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_orders__accountId ON c_orders (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_orders__stripeSessionId ON c_orders (json_extract(data, '$.stripeSessionId') ASC);
CREATE INDEX IF NOT EXISTS i_orders__stripePaymentIntentId ON c_orders (json_extract(data, '$.stripePaymentIntentId') ASC) WHERE json_type(data, '$.stripePaymentIntentId') = 'text';
CREATE INDEX IF NOT EXISTS i_orders__accountId__createdAt_d___id_d ON c_orders (accountId ASC, json_extract(data, '$.createdAt') DESC, _id DESC);
CREATE INDEX IF NOT EXISTS i_orders__productId__createdAt_d ON c_orders (json_extract(data, '$.productId') ASC, json_extract(data, '$.createdAt') DESC);
CREATE INDEX IF NOT EXISTS i_orders__accountId__buyerEmail ON c_orders (accountId ASC, json_extract(data, '$.buyerEmail') ASC);
CREATE TABLE IF NOT EXISTS c_paymentevents (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_paymentevents__accountId ON c_paymentevents (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_paymentevents__eventId ON c_paymentevents (json_extract(data, '$.eventId') ASC);
CREATE INDEX IF NOT EXISTS i_paymentevents__createdAt ON c_paymentevents (json_extract(data, '$.createdAt') ASC);
CREATE TABLE IF NOT EXISTS c_products (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_products__accountId ON c_products (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_products__newsletterId__slug ON c_products (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.slug') ASC);
CREATE INDEX IF NOT EXISTS i_products__newsletterId__status__createdAt_d ON c_products (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.status') ASC, json_extract(data, '$.createdAt') DESC);
CREATE INDEX IF NOT EXISTS i_products__accountId__createdAt_d___id_d ON c_products (accountId ASC, json_extract(data, '$.createdAt') DESC, _id DESC);
